function roundHalfUp(value) {
  return Math.floor(value + 0.5);
}

module.exports = { roundHalfUp };

files.invoice.js:
const { roundHalfUp } = require("./round.js");

function lineTotal(price, quantity) {
  return roundHalfUp(price * quantity);
}

module.exports = { lineTotal };

