const test = require("node:test");
const assert = require("node:assert/strict");
const { roundHalfUp } = require("../round.js");

test("rounds positive amounts to nearest integer", () => {
  assert.equal(roundHalfUp(10.4), 10);
  assert.equal(roundHalfUp(10.5), 11);
});
